/**
 * Community build data from Fribbels' HSR Optimizer (MIT licence): substat weights, main stats per
 * slot, recommended relic and ornament sets, best teammates and default Light Cone.
 * Generated by scripts/import-fribbels.mjs into src/data/fribbels-builds.json.
 */
import data from "@/data/fribbels-builds.json";
import type { GameData } from "../gamedata/types";
import type { ScoringProfile } from "../relics/scoring";
import type { MainStatKey, RelicSlot, SubStatKey } from "../relics/stats";

export interface FribbelsBuild {
  name: string;
  weights: Partial<Record<SubStatKey, number>>;
  mainStats: Partial<Record<RelicSlot, MainStatKey[]>>;
  substats?: SubStatKey[];
  relicSets?: string[][];
  ornamentSets?: string[];
  teammates?: { id: string; lightCone: string | null }[];
  defaultLightCone?: string;
}

export const FRIBBELS = {
  source: data.source,
  commit: data.commit,
  license: data.license,
  generated: data.generated,
  url: `${data.source}/tree/${data.commit}`,
} as const;

const BUILDS = data.characters as unknown as Record<string, FribbelsBuild>;

/** Female Trailblazers (even ids 8002, 8004, …) share the male variant's build (odd id one lower). */
function lookupId(charId: string): string {
  if (BUILDS[charId]) return charId;
  const n = Number(charId);
  if (n >= 8000 && n < 9000 && n % 2 === 0 && BUILDS[String(n - 1)]) return String(n - 1);
  return charId;
}

export function fribbelsBuild(charId: string): FribbelsBuild | null {
  return BUILDS[lookupId(charId)] ?? null;
}

/** Fribbels' weights as a scoring profile (used when you haven't customised one). */
export function fribbelsProfile(charId: string): ScoringProfile | null {
  const b = fribbelsBuild(charId);
  if (!b || !Object.keys(b.weights).length) return null;
  return {
    id: `fribbels-${charId}`,
    name: "Community (Fribbels)",
    weights: b.weights,
    mainStats: b.mainStats,
    origin: "template",
    templateId: "fribbels",
    note: "Substat weights and main stats from Fribbels' HSR Optimizer.",
  };
}

/** Resolve Fribbels set names to this game data's set ids; unknown names are dropped. */
export function setIdsByName(game: GameData): Map<string, string> {
  return new Map(Object.values(game.relicSets).map((s) => [s.name, s.id]));
}

/** Substat priority: Fribbels' explicit order when present, otherwise by weight. */
export function substatOrder(b: FribbelsBuild): SubStatKey[] {
  if (b.substats?.length) return b.substats;
  return (Object.entries(b.weights) as [SubStatKey, number][]).filter(([, w]) => w > 0).sort((x, y) => y[1] - x[1]).map(([k]) => k);
}
